const pptxgen = require("pptxgenjs");
const pres = new pptxgen();
pres.layout = "LAYOUT_WIDE"; // 13.333 x 7.5, same as Part 1
pres.title = "Building an agent that works";

const NAVY = "1E2761", ICE = "CADCFC", LIGHT = "F4F6FB", INK = "1A1A2E", MUTED = "6B7280";
const ORANGE = "F2A65A", ORANGE_DK = "B4532A", GREEN = "2E9E6D", GREEN_LT = "8FD9B4", WHITE = "FFFFFF";
const HEAD = "Cambria", BODY = "Calibri";
const L = 0.6, R = 12.733, W = R - L;

const shadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 2, angle: 90, opacity: 0.12 });

function text(slide, t, o) {
  slide.addText(t, Object.assign({ isTextBox: true, fontFace: BODY, color: INK, margin: 0, valign: "top" }, o));
}
function label(slide, t, x, y, w, color = NAVY) {
  text(slide, t.toUpperCase(), { x, y, w, h: 0.28, fontSize: 10.5, bold: true, color, charSpacing: 0.5 });
}
function header(slide, n, title) {
  slide.background = { color: WHITE };
  slide.addShape(pres.shapes.OVAL, { x: L, y: 0.58, w: 0.55, h: 0.55, fill: { color: NAVY }, line: { color: NAVY } });
  text(slide, String(n), { x: L, y: 0.58, w: 0.55, h: 0.55, fontFace: HEAD, fontSize: 17, bold: true, color: WHITE, align: "center", valign: "middle" });
  text(slide, title, { x: 1.35, y: 0.5, w: 11.2, h: 0.72, fontFace: HEAD, fontSize: 30, bold: true, color: NAVY, valign: "middle" });
}
function card(slide, x, y, w, h, fill, withShadow = false) {
  const o = { x, y, w, h, fill: { color: fill }, line: { color: fill }, rectRadius: 0.06 };
  if (withShadow) o.shadow = shadow();
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, o);
}
function quote(slide, main, sub, y, x = L, w = W) {
  card(slide, x, y, w, 0.7, LIGHT, true);
  const runs = [{ text: main, options: { fontFace: HEAD, italic: true, color: NAVY, fontSize: 16 } }];
  if (sub) runs.push({ text: "   " + sub, options: { fontFace: BODY, color: MUTED, fontSize: 13 } });
  text(slide, runs, { x: x + 0.3, y, w: w - 0.6, h: 0.7, valign: "middle" });
}
